import{D as e,f as t,u as n}from"./runtime-core.esm-bundler-BHJ3o1LK.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/%E9%A1%B9%E7%9B%AE/%E9%9D%A2%E8%AF%95%E5%8A%A9%E6%89%8B/%E5%89%8D%E7%AB%AF%E5%AE%9E%E7%8E%B0/%E6%A8%A1%E6%8B%9F%E9%9D%A2%E8%AF%95%E7%AC%AC%E4%BA%8C%E7%89%88-%E6%96%87%E5%AD%97%E4%BD%9C%E7%AD%94%E4%B8%8E%E5%AE%9E%E6%97%B6%E8%AF%AD%E9%9F%B3%E8%BE%93%E5%85%A5%E6%96%B9%E6%A1%88.html","title":"模拟面试第二版-文字作答与实时语音输入方案","lang":"zh-CN","frontmatter":{"title":"模拟面试第二版-文字作答与实时语音输入方案","icon":"mdi:microphone-message","sort":10,"description":"模拟面试第二版：文字作答 + 实时语音输入方案 文档定位：前端实现方案 + 本次落地记录。 第二版（下称 V2）把模拟面试从「实时语音通话」改为「发消息作答」，形态对齐 AI 问答； 语音退化为输入辅助（话筒按钮 → 实时语音识别 → 文本写入输入框），不再是整场音频上行。 旧版（下称 V1）页面保留不删，两版并存。 本次范围：页面与交互、语音输入的通...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"模拟面试第二版-文字作答与实时语音输入方案\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-09-24T10:14:05.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"桥黎\\",\\"url\\":\\"\\"}]}"],["meta",{"property":"og:url","content":"https://docs.cqlql.top/%E9%A1%B9%E7%9B%AE/%E9%9D%A2%E8%AF%95%E5%8A%A9%E6%89%8B/%E5%89%8D%E7%AB%AF%E5%AE%9E%E7%8E%B0/%E6%A8%A1%E6%8B%9F%E9%9D%A2%E8%AF%95%E7%AC%AC%E4%BA%8C%E7%89%88-%E6%96%87%E5%AD%97%E4%BD%9C%E7%AD%94%E4%B8%8E%E5%AE%9E%E6%97%B6%E8%AF%AD%E9%9F%B3%E8%BE%93%E5%85%A5%E6%96%B9%E6%A1%88.html"}],["meta",{"property":"og:site_name","content":"开发笔记"}],["meta",{"property":"og:title","content":"模拟面试第二版-文字作答与实时语音输入方案"}],["meta",{"property":"og:description","content":"模拟面试第二版：文字作答 + 实时语音输入方案 文档定位：前端实现方案 + 本次落地记录。 第二版（下称 V2）把模拟面试从「实时语音通话」改为「发消息作答」，形态对齐 AI 问答； 语音退化为输入辅助（话筒按钮 → 实时语音识别 → 文本写入输入框），不再是整场音频上行。 旧版（下称 V1）页面保留不删，两版并存。 本次范围：页面与交互、语音输入的通..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-09-24T10:14:05.000Z"}],["meta",{"property":"article:modified_time","content":"2026-09-24T10:14:05.000Z"}]]},"git":{"createdTime":1790071903000,"updatedTime":1790244845000,"contributors":[{"name":"cql","username":"cql","email":"cql.ql@qq.com","commits":3,"url":"https://github.com/cql"}]},"readingTime":{"minutes":44.91,"words":13474},"filePathRelative":"项目/面试助手/前端实现/模拟面试第二版-文字作答与实时语音输入方案.md","autoDesc":true}`),a={name:`模拟面试第二版-文字作答与实时语音输入方案.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="模拟面试第二版-文字作答-实时语音输入方案" tabindex="-1"><a class="header-anchor" href="#模拟面试第二版-文字作答-实时语音输入方案"><span>模拟面试第二版：文字作答 + 实时语音输入方案</span></a></h1><blockquote><p>文档定位：<strong>前端实现方案 + 本次落地记录</strong>。 第二版（下称 V2）把模拟面试从「实时语音通话」改为「发消息作答」，形态对齐 AI 问答； 语音退化为<strong>输入辅助</strong>（话筒按钮 → 实时语音识别 → 文本写入输入框），不再是整场音频上行。 旧版（下称 V1）页面<strong>保留不删</strong>，两版并存。 本次范围：页面与交互、语音输入的通道抽象、路由与入口开关。</p></blockquote><p><strong>当前状态（2026-09-23，以仓库为准）</strong>：</p><table><thead><tr><th style="text-align:left;">部分</th><th style="text-align:left;">状态</th></tr></thead><tbody><tr><td style="text-align:left;">前端页面与语音输入抽象（<code>pages/mock-interview-v2</code>、<code>features/speech</code>、设置页 <code>?mode=text</code>）</td><td style="text-align:left;">✅ 已完成（已提交，不再挂在 <code>stash</code> 上）</td></tr><tr><td style="text-align:left;">后端「文字作答」（<code>input=text</code> + V26 + <code>ANSWER</code> + 回合串行化）</td><td style="text-align:left;">✅ <strong>已完成</strong>（后端方案 Step 1）</td></tr><tr><td style="text-align:left;">前端接线（建连带 <code>input=text</code>、发 <code>ANSWER</code>、消费 <code>TURN_BUSY</code> 等错误码）</td><td style="text-align:left;">✅ <strong>已完成（2026-09-23）</strong>：见 §6.1 的「落地记录」</td></tr><tr><td style="text-align:left;">后端 <code>/ws/asr</code> 识别通道</td><td style="text-align:left;">✅ <strong>已完成</strong>（后端 Step 2）</td></tr><tr><td style="text-align:left;">前端 <code>/ws/asr</code> 接入（实现 <code>AsrTransport</code>）</td><td style="text-align:left;">✅ <strong>已完成（2026-09-23）</strong>：见 §6.2 的「落地记录」</td></tr><tr><td style="text-align:left;">前端语音输入的<strong>资源生命周期</strong>收口（<code>useSpeechInput</code> 的 <code>enabled</code> / <code>terminated</code>）</td><td style="text-align:left;">✅ <strong>已完成（2026-09-24）</strong>：暂停/AI 生成中只停录音，面试结束直接释放识别通道 —— 见 §6.2 的「生命周期收口」</td></tr><tr><td style="text-align:left;">后端 <code>/ws/asr</code> 资格挂靠面试会话（建连资格闸门 + 面试结束回收识别连接）</td><td style="text-align:left;">✅ <strong>已完成（2026-09-24）</strong>（后端方案 §4.2.5 / Step 4）；前端已登记 4007，<strong>不需要新增建连参数</strong>（见 §6.2）</td></tr></tbody></table><blockquote><p><strong>协议事实的唯一来源</strong>：本文档<strong>不定义协议</strong>，只描述&quot;前端怎么实现、怎么消费&quot;。 消息形态、建连参数、错误码、会话就绪点、心跳/计费判据一律以 <strong>后端方案《模拟面试第二版-语音识别与LLM回合解耦方案》+ 两端协议文件</strong> （<code>apps/user/src/features/realtime-voice/hooks/protocol.ts</code>、<code>src/features/interview/ws.ts</code>）为准。 两边不一致时，改的是<strong>引用方（本文档）</strong>，不是在这里再抄一份协议定义 —— 本轮已经在这里发生过一次漂移（本文档写&quot;后端 ASR 已就绪&quot;，后端方案写&quot;Step 2 未开始&quot;）。</p></blockquote><h2 id="_1-背景与目标" tabindex="-1"><a class="header-anchor" href="#_1-背景与目标"><span>1. 背景与目标</span></a></h2><h3 id="_1-1-要解决的问题" tabindex="-1"><a class="header-anchor" href="#_1-1-要解决的问题"><span>1.1 要解决的问题</span></a></h3><p>V1 的整场音频上行（<code>/ws/audio</code> 二进制 PCM 帧）有三个连带成本：</p><table><thead><tr><th style="text-align:left;">问题</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">网络与稳定性</td><td style="text-align:left;">每分钟约 60KB/s 的持续上行，网络抖动直接表现为卡顿、断连</td></tr><tr><td style="text-align:left;">用户表达成本</td><td style="text-align:left;">必须「说完」才能被识别，思考型用户（面试做题思路）被迫在语音里组织语言</td></tr><tr><td style="text-align:left;">环境限制</td><td style="text-align:left;">开会、办公室、图书馆等场景无法开口说话</td></tr></tbody></table><p>V2 的目标：<strong>默认用文字作答</strong>，让「不愿/不便开口」的用户能完成整场模拟面试；语音只作为想偷懒时的快捷输入。</p><h3 id="_1-2-目标形态" tabindex="-1"><a class="header-anchor" href="#_1-2-目标形态"><span>1.2 目标形态</span></a></h3><ul><li>交互形态对齐 <code>pages/ai-qa</code>：气泡对话 + 底部输入区，用户发一条、AI 面试官回一条（流式）。</li><li>输入框右侧一个<strong>话筒按钮</strong>：点击开始实时语音识别，识别文本实时写入输入框。</li><li>V1 的会话语义（一场面试、时长计费、面试记录、暂停恢复）<strong>不因形态变化而消失</strong>，接入时需继续满足（见 6.3）。</li></ul><h2 id="_2-现状与可复用资产" tabindex="-1"><a class="header-anchor" href="#_2-现状与可复用资产"><span>2. 现状与可复用资产</span></a></h2><table><thead><tr><th style="text-align:left;">资产</th><th style="text-align:left;">位置</th><th style="text-align:left;">V2 如何复用</th></tr></thead><tbody><tr><td style="text-align:left;">对话气泡列表</td><td style="text-align:left;"><code>components/ChatList</code></td><td style="text-align:left;">直接复用（<code>Message{role:&#39;ai&#39;|&#39;user&#39;}</code> + <code>textSize</code>）</td></tr><tr><td style="text-align:left;">文字大小设置</td><td style="text-align:left;">storage <code>mock_interview_text_size</code></td><td style="text-align:left;">复用同一 key，设置页改一次两版都生效</td></tr><tr><td style="text-align:left;">面试配置（语言/详细程度/风格/模板）</td><td style="text-align:left;">设置页写入 storage</td><td style="text-align:left;">复用同一批 key（接口接入时读取）</td></tr><tr><td style="text-align:left;">面试准备与资料校验</td><td style="text-align:left;"><code>mock-interview-setting</code> + <code>features/interview/hooks/useInterviewPrepData</code></td><td style="text-align:left;">复用设置页与 <code>?mode=text</code> 入口，校验逻辑不变</td></tr><tr><td style="text-align:left;">页面埋点</td><td style="text-align:left;"><code>features/analytics</code></td><td style="text-align:left;">复用 <code>usePageView</code>，页面名区分为「模拟面试-文字版」</td></tr><tr><td style="text-align:left;">音频采集参数</td><td style="text-align:left;"><code>features/interview/recorder.ts</code>（16kHz/16bit/单声道 PCM、<code>frameSize: 4</code>）</td><td style="text-align:left;">语音输入的采集参数与之对齐，保证后端 ASR 可直接吃帧</td></tr></tbody></table><p>V1 页面 <code>pages/mock-interview/index.tsx</code> 与 <code>features/interview/recorder.ts</code> <strong>未做任何改动</strong>； <code>features/interview/ws.ts</code> 只做了<strong>纯增量</strong>的 V2 协议登记（<code>input</code> 建连参数、<code>sendAnswer()</code>、4 个错误码）， V1 行为不变 —— 见 §6.1 与 §7。</p><h2 id="_3-结论与本次范围" tabindex="-1"><a class="header-anchor" href="#_3-结论与本次范围"><span>3. 结论与本次范围</span></a></h2><h3 id="_3-1-本次已落地" tabindex="-1"><a class="header-anchor" href="#_3-1-本次已落地"><span>3.1 本次已落地</span></a></h3><blockquote><p>⚠️ <strong>本节这些成果目前都在 <code>stash@{0}</code> 里（未提交、不在 <code>frontend-mp</code> 分支上）</strong> —— 见 §7 的说明。</p></blockquote><ul><li>新页面 <code>pages/mock-interview-v2/index</code>：气泡对话 + 输入区 + 话筒按钮 + 免责声明条。</li><li>新能力模块 <code>features/speech/</code>：语音识别器、传输层抽象、<code>useSpeechInput</code> Hook。</li><li>路由注册（<code>app.config.ts</code>）与入口开关（设置页 <code>?mode=text</code>，默认仍是 V1）。</li><li>开发期直达入口：demo 页新增两条（V2 页面、V2 设置入口）。</li></ul><h3 id="_3-2-本次故意未做" tabindex="-1"><a class="header-anchor" href="#_3-2-本次故意未做"><span>3.2 本次故意未做</span></a></h3><ul><li><s><strong>不发任何业务请求</strong>：发送回答只落到本地消息列表，不伪造面试官回复（见 <code>index.tsx</code> 的 TODO）。</s> ✅ <strong>已接入（2026-09-23）</strong>：作答走上行 <code>ANSWER</code>，AI 追问以 <code>THINKING</code> + <code>LLM_REPLY</code> 流式回来（见 §6.1）。</li><li><s><strong>语音识别只搭骨架</strong>：不接识别服务，点话筒会明确提示「实时语音识别接口待接入」。</s> ✅ <strong>已接入（2026-09-23）</strong>：<code>AsrTransport</code> 已换成 <code>/ws/asr</code> 真实传输（见 §6.2）。</li><li><strong>不引入任何第三方依赖</strong>：没有安装 npm 包，也没有引入微信插件（见 5.2 的方案取舍）。</li><li><strong>不做&quot;无操作自动暂停&quot;</strong>：思考时间计入面试时长（已定稿，后端方案 §8 P0-1）。</li></ul><h2 id="_4-页面设计" tabindex="-1"><a class="header-anchor" href="#_4-页面设计"><span>4. 页面设计</span></a></h2><h3 id="_4-1-路由与入口" tabindex="-1"><a class="header-anchor" href="#_4-1-路由与入口"><span>4.1 路由与入口</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>面试助手首页「步骤一：模拟面试」</span></span>
<span class="line"><span>  └─ /pages/mock-interview-setting/index            → 开始面试 → /pages/mock-interview/index     （V1，默认，行为不变）</span></span>
<span class="line"><span>  └─ /pages/mock-interview-setting/index?mode=text  → 开始面试 → /pages/mock-interview-v2/index  （V2）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>设置页用 <code>useRouter().params.mode</code> 判定形态，<strong>不传即 V1</strong>，因此现有入口完全不受影响。</li><li>V2 下不校验麦克风授权、也不显示「请先授权麦克风权限」的拦截提示：文字作答不需要麦克风，语音输入是可选项，权限在点话筒时才申请。</li><li>入口是否切到 V2（甚至砍掉 V1）属产品决策，留待接口接入后再定，见第 9 节。</li></ul><blockquote><p>⚠️ <strong><code>?mode=text</code> 不是后端的 <code>input=text</code> —— 两者不能互相透传</strong>（接线时最容易踩的一处）：</p><table><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">含义</th><th style="text-align:left;">取值</th><th style="text-align:left;">归属</th></tr></thead><tbody><tr><td style="text-align:left;">页面参数 <code>?mode=text</code>（设置页 → 页面）</td><td style="text-align:left;">选<strong>页面形态</strong>（V1 语音版 / V2 文字版）</td><td style="text-align:left;"><code>text</code> / 不传</td><td style="text-align:left;">前端路由</td></tr><tr><td style="text-align:left;">WS 建连参数 <code>input=text</code></td><td style="text-align:left;">选<strong>作答方式</strong>（起不起 ASR、收不收 <code>ANSWER</code>）</td><td style="text-align:left;"><code>audio</code> / <code>text</code></td><td style="text-align:left;">后端会话</td></tr><tr><td style="text-align:left;">WS 建连参数 <code>mode=mock</code></td><td style="text-align:left;">选<strong>面试模式</strong>（AI 是面试官还是求职者）</td><td style="text-align:left;"><code>assist</code> / <code>mock</code></td><td style="text-align:left;">后端会话</td></tr></tbody></table><p>V2 建连是 <code>mode=mock</code> + <code>input=text</code>。若把页面的 <code>mode=text</code> 直接透传： 后端 <code>InterviewMode.from(&#39;text&#39;)</code> 会<strong>静默回退成 <code>ASSIST</code></strong>，随后被 <code>assist + text</code> 组合校验拒掉 —— 表现为&quot;建连就失败&quot;，但根因是页面参数被当成了会话参数。</p></blockquote><h3 id="_4-2-页面结构" tabindex="-1"><a class="header-anchor" href="#_4-2-页面结构"><span>4.2 页面结构</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>┌──────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 模拟面试            剩余 12:34 [暂停][结束] │  ← 顶栏：左＝标题 + 状态提示；右＝剩余时长 + 操作</span></span>
<span class="line"><span>│ 面试进行中                                 │</span></span>
<span class="line"><span>├──────────────────────────────────────────┤</span></span>
<span class="line"><span>│  ● 面试官开场白（AI 气泡，左）             │  ← ChatList（复用）</span></span>
<span class="line"><span>│                       用户回答 ●（右）    │</span></span>
<span class="line"><span>├──────────────────────────────────────────┤</span></span>
<span class="line"><span>│ （暂停态才出现）面试已暂停…      [继续面试]  │  ← 暂停条</span></span>
<span class="line"><span>├──────────────────────────────────────────┤</span></span>
<span class="line"><span>│ （识别中才出现）● 正在聆听，说话内容会实时…  │  ← 语音识别状态条</span></span>
<span class="line"><span>├──────────────────────────────────────────┤</span></span>
<span class="line"><span>│ [ 输入你的回答…        ] (话筒) (发送)     │  ← 输入区</span></span>
<span class="line"><span>├──────────────────────────────────────────┤</span></span>
<span class="line"><span>│            内容由AI生成，仅供参考          │  ← 免责声明（与 V1 一致）</span></span>
<span class="line"><span>└──────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>尺寸单位统一 <code>px</code>（<code>designWidth: 375</code>，与 <code>mock-interview-setting</code>、<code>formal-interview-assistant</code> 等新页面一致）。</li><li>底部预留 <code>env(safe-area-inset-bottom)</code>，避免全面屏机型压住免责声明。</li><li><strong>操作集中在顶栏</strong>（2026-09-23 调整）：剩余时长 / 暂停（暂停态为「继续」）/ 结束都在头部右侧， 做成竖向圆角胶囊（<code>align-self: stretch</code> + 上下 10px 边距，随头部高度自适应）； 底部只留输入区与免责声明。<strong>没有「文字作答」形态标签</strong>（入口已经区分形态，标签是冗余信息）。</li><li>输入胶囊（<code>input-wrapper</code>）<strong>外层不留 padding</strong>：留白一律下沉到子元素（文本缩进给原生 <code>input</code> 的 padding， 按钮的视觉圆形留给内层 <code>*-inner</code>，外层 42px 只作热区），否则外层留白是&quot;看起来有边距、点上去没反应&quot;的死区。</li></ul><h3 id="_4-3-交互" tabindex="-1"><a class="header-anchor" href="#_4-3-交互"><span>4.3 交互</span></a></h3><table><thead><tr><th style="text-align:left;">操作</th><th style="text-align:left;">行为</th></tr></thead><tbody><tr><td style="text-align:left;">输入后点发送（或键盘回车）</td><td style="text-align:left;">追加用户气泡 → 清空输入框 → 上传 <code>ANSWER</code>，AI 追问以 <code>loading</code> 气泡占位并逐字填充</td></tr><tr><td style="text-align:left;">发送后（AI 未回复完）</td><td style="text-align:left;"><strong>输入框与发送按钮禁用</strong>（这是 <code>TURN_BUSY</code> 的语义要求，见 §6.1）；收到 <code>LLM_REPLY.final</code> 或 <code>ERROR</code> 后恢复</td></tr><tr><td style="text-align:left;">点话筒（空闲）</td><td style="text-align:left;">申请麦克风权限 → 开始识别 → 按钮变红并出现状态条</td></tr><tr><td style="text-align:left;">点话筒（识别中）</td><td style="text-align:left;">结束识别（<code>stop</code>），保留已识别文本；识别连接由 transport 在<strong>空闲 ~8 秒后自动释放</strong></td></tr><tr><td style="text-align:left;">点发送（识别中）</td><td style="text-align:left;"><strong>先停识别再发送</strong>（<code>useSpeechInput</code> 的 <code>stop()</code>）：输入框马上要清空，识别结果再写回来会变成&quot;幽灵文字&quot;（用户没说的话出现在空输入框里）</td></tr><tr><td style="text-align:left;">录音达到单次上限（<strong>180 秒</strong>，<code>MAX_RECORDING_MS</code>）</td><td style="text-align:left;">录音由微信自动停止，<strong>明确提示「已到单次语音上限，可再点话筒继续说」</strong>，不能静默停止（否则用户会以为识别坏了）。<strong>界面上不显示已用时长</strong>（2026-09-24 决定：提示条只写&quot;正在聆听…&quot;，不拿数字分散注意力）</td></tr><tr><td style="text-align:left;">输入为空</td><td style="text-align:left;">发送按钮置灰不可点；同时前端做长度拦截（上限 2000 字，后端会拒）</td></tr><tr><td style="text-align:left;">点「暂停」（进行中时出现在头部）</td><td style="text-align:left;">先弹确认（暂停会取消在途回复、超 15 分钟面试就结束，值得挡一下）→ <strong>同时立即停止语音输入</strong>（只停录音与推帧；识别通道由 transport 在空闲 ~8 秒后自行释放）→ 发 <code>PAUSE</code> → 收 <code>PAUSED</code> 后进入暂停态：输入区禁用、底部出现暂停条 + 「继续面试」，<strong>头部同一位置也由「暂停」变为「继续」</strong>；暂停<strong>不往对话流里补记录</strong>（暂停是状态，不是对话内容，状态栏已有提示）</td></tr><tr><td style="text-align:left;">点「继续面试」/ 头部「继续」（暂停态）</td><td style="text-align:left;">两处等价，都是 <code>handleResume</code>；用 <code>resume=&lt;逻辑会话ID&gt;</code> 重连：<strong>复用原上下文与计费，不重发首问</strong>；超时或记录不可恢复 → <code>RESUME_EXPIRED</code> / <code>RESUME_FORBIDDEN</code> → 提示&quot;暂停会话已失效，请重新开始面试&quot;</td></tr><tr><td style="text-align:left;">点头部「结束」（红胶囊，与「暂停 / 继续」并列）</td><td style="text-align:left;">断开连接 → 提示「面试已结束」→ 600ms 后跳转：<strong>用了通用模板进「体验完成」引导页</strong>，否则返回上一页（细节见 §6.3.3）；<strong>语音输入通道随之释放</strong>（<code>terminated</code> → <code>dispose()</code>，页面不手工调用）</td></tr></tbody></table><h2 id="_5-实时语音识别方案" tabindex="-1"><a class="header-anchor" href="#_5-实时语音识别方案"><span>5. 实时语音识别方案</span></a></h2><h3 id="_5-1-分层" tabindex="-1"><a class="header-anchor" href="#_5-1-分层"><span>5.1 分层</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>页面（mock-interview-v2）</span></span>
<span class="line"><span>  └─ useSpeechInput（features/speech/hooks）      ← 权限申请、识别文本与输入框的合并规则、卸载释放</span></span>
<span class="line"><span>       └─ SpeechRecognizer（features/speech）      ← 平台判定、录音采集、生命周期收尾、错误归一</span></span>
<span class="line"><span>            └─ AsrTransport（features/speech）     ← 【唯一待接入点】把 PCM 帧送出去、把文本收回来</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>接入识别服务只需要实现 <code>AsrTransport</code> 并在 <code>createAsrTransport()</code> 里换掉返回值</strong>，页面与 Hook 无需改动。</p><h3 id="_5-2-路线取舍-方案-a-已定稿-b-仅作历史备选" tabindex="-1"><a class="header-anchor" href="#_5-2-路线取舍-方案-a-已定稿-b-仅作历史备选"><span>5.2 路线取舍（方案 A 已定稿，B 仅作历史备选）</span></a></h3><table><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">方案 A：服务端流式 ASR（推荐）</th><th style="text-align:left;">方案 B：微信同声传译插件 WechatSI</th></tr></thead><tbody><tr><td style="text-align:left;">文本来源</td><td style="text-align:left;">后端 ASR，前端推 PCM 帧、收识别文本</td><td style="text-align:left;">插件内置识别，零后端</td></tr><tr><td style="text-align:left;">前端改动</td><td style="text-align:left;">实现 <code>AsrTransport</code>（新通道，如 <code>/ws/asr</code>）</td><td style="text-align:left;">页面配置声明插件 + 换 Hook 内部实现，<code>AsrTransport</code> 不再需要</td></tr><tr><td style="text-align:left;">跨端</td><td style="text-align:left;">采集能力本来就仅微信端，与 A 相同</td><td style="text-align:left;">仅微信端</td></tr><tr><td style="text-align:left;">额外成本</td><td style="text-align:left;">后端需提供识别通道</td><td style="text-align:left;"><strong>需在小程序后台添加插件</strong>、需用户授权该插件</td></tr><tr><td style="text-align:left;">与面试链路</td><td style="text-align:left;"><strong>通道独立、资格挂靠</strong>：不产生面试计费、不触发 AI 回复；但必须有进行中的面试才能建连（后端方案 §4.2.5）</td><td style="text-align:left;">完全独立</td></tr><tr><td style="text-align:left;">风险</td><td style="text-align:left;">需要后端配合</td><td style="text-align:left;">插件不可用/未授权时无法自愈，构建与运行都依赖后台配置</td></tr></tbody></table><blockquote><p><strong>已定稿：正式方案是 A（服务端流式 ASR）。</strong> 方案 B（微信同声传译插件）<strong>不进入实现范围</strong>，仅作为历史备选保留上表： 它引入的是插件声明 + 后台配置 + 用户授权三层外部依赖，且会与既有 ASR 能力形成两套语音输入链路； 而后端方案 §3 已经做了同样的取舍（A / B / C 三选一，结论 A），并明确&quot;识别不依赖任何第三方插件&quot;。</p><p><strong>A 的落地节奏</strong>：前端已经把通道抽象出来（<code>AsrTransport</code> 留桩）；<strong>后端 <code>/ws/asr</code> 也已交付</strong> （2026-09-22，后端 Step 2：路由 + 轻量鉴权 + 并发/时长上限，复用 <code>AsrStreamRunner</code>）。 因此现在唯一缺的就是<strong>前端把 <code>AsrTransport</code> 的占位实现换成真实传输</strong>（协议见 §6.2）。</p></blockquote><p>还有一条<strong>不推荐</strong>的取巧路线：复用现有 <code>/ws/audio</code> 的音频上行，只取回包的 <code>ASR_RESULT</code> 而忽略 <code>LLM_REPLY</code>。它会让每次语音输入都额外产生一场面试会话与时长消耗，且 AI 会同时抢答，仅在「后端支持纯识别模式」时才值得考虑。</p><h3 id="_5-3-识别文本写入输入框的规则" tabindex="-1"><a class="header-anchor" href="#_5-3-识别文本写入输入框的规则"><span>5.3 识别文本写入输入框的规则</span></a></h3><p>以「基准 + 草稿」两段式合并，保证<strong>边说边改</strong>不覆盖用户已输入的文字：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>点话筒那一刻：base = 输入框当前内容，draft = &#39;&#39;</span></span>
<span class="line"><span>收到 final=false（流式中间态）：draft = 该片段        → 输入框 = base + draft</span></span>
<span class="line"><span>收到 final=true （定稿）      ：base = base + 片段，draft = &#39;&#39; → 输入框 = base</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>中间态是<strong>覆盖</strong>而非追加，否则会出现「我我我想想」这类叠字。</li><li>定稿后 <code>base</code> 才前进，因此连续说多句会依次追加，标点随服务端结果带回。</li><li>用户手动输入的内容作为 <code>base</code> 起点保留，不会被识别结果清空。</li><li><code>value/onChange/onError</code> 通过 ref 读取最新值，避免识别过程中每次结果触发重渲染而拿到旧闭包。</li></ul><p><strong>边界：识别过程中用户手动改字（补一条，否则会覆盖用户刚改的内容）</strong></p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>ASR 识别中 → 用户手动改了输入框 → 后续 ASR 中间结果到达</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ul><li>规则：<strong>用户一旦手动编辑，就视为&quot;用户接管输入&quot;</strong> —— 把 <code>base</code> 重置为&quot;用户编辑后的输入框内容&quot;、 <code>draft</code> 清空；之后 ASR 结果继续按&quot;中间态覆盖 <code>draft</code> / 定稿追加 <code>base</code>&quot;处理， <strong>不再回滚用户改过的内容</strong>。</li><li>实现：<code>onChange</code> 里区分&quot;程序写入&quot;与&quot;用户输入&quot;（程序写入时置一次性标记）， 非程序触发的 <code>onChange</code> ⇒ <code>base = 最新值; draft = &#39;&#39;</code>。</li><li>为什么必须定义：两段式只解决&quot;边说边改&quot;，没解决&quot;人机同时改&quot; —— 用户把 <code>Redis</code> 改成 <code>Redis Cluster</code>，下一个中间态会把改动吃掉。</li></ul><h3 id="_5-4-跨端与降级" tabindex="-1"><a class="header-anchor" href="#_5-4-跨端与降级"><span>5.4 跨端与降级</span></a></h3><ul><li>实时帧回调（<code>RecorderManager.onFrameRecorded</code>）<strong>是小程序专属能力</strong>，H5/其他端无等价实现。</li><li>识别器构造时即判定 <code>process.env.TARO_ENV === &#39;weapp&#39;</code>，非微信端点话筒直接返回 <code>UNSUPPORTED_PLATFORM</code>，页面提示「当前端暂不支持实时语音识别，请手动输入」——<strong>输入框与发送链路不受影响</strong>。</li><li>因此 V2 页面在 H5 端可用（只是不能语音输入），不违反跨端规范。</li></ul><h3 id="_5-5-权限与错误处理" tabindex="-1"><a class="header-anchor" href="#_5-5-权限与错误处理"><span>5.5 权限与错误处理</span></a></h3><table><thead><tr><th style="text-align:left;">时机</th><th style="text-align:left;">处理</th></tr></thead><tbody><tr><td style="text-align:left;">首次点话筒</td><td style="text-align:left;"><code>Taro.getSetting</code> 查 <code>scope.record</code> → 未授权则 <code>Taro.authorize</code></td></tr><tr><td style="text-align:left;">用户此前拒绝过</td><td style="text-align:left;"><code>authorize</code> 不再弹窗，弹 <code>showModal</code> 引导「去设置」→ <code>Taro.openSetting()</code></td></tr><tr><td style="text-align:left;">录音失败</td><td style="text-align:left;"><code>onError</code> 归一为 <code>RECORD_FAILED</code>，页面 Toast 提示，同时清理通道（不留下挂着麦克风的空会话）</td></tr><tr><td style="text-align:left;">识别通道不可用</td><td style="text-align:left;"><code>transport.start()</code> <strong>返回 Promise，失败即 reject</strong>（凭证失效 / <strong>没有进行中的面试</strong> / 并发超限 / 配额用完都走这条），<strong>不启动录音</strong>（不开一个没有出口的麦克风）</td></tr><tr><td style="text-align:left;">面试<strong>暂停</strong> / AI 正在回复</td><td style="text-align:left;"><code>enabled=false</code> → <code>stop()</code>：停录音与推帧、<code>listening</code> 归位；连接由 transport 在<strong>空闲 ~8 秒后自行释放</strong>（恢复后再点话筒会新建一条 —— <code>start()</code> 本来也会先释放旧的）</td></tr><tr><td style="text-align:left;">面试<strong>结束</strong>（主动结束 / 掉线 / 余额耗尽 / 暂停超时）</td><td style="text-align:left;"><code>terminated=true</code> → <code>dispose()</code>：真正关闭 <code>/ws/asr</code>，并把 <code>listening</code> 归位；此后到达的识别结果 / 错误 / 超时提示<strong>一律丢弃</strong></td></tr><tr><td style="text-align:left;">离开页面</td><td style="text-align:left;"><code>dispose()</code>：停录音、释放通道；<code>dispose</code> 后忽略一切异步回调</td></tr><tr><td style="text-align:left;">单次时长上限</td><td style="text-align:left;">录音 <code>duration: MAX_RECORDING_MS</code>（<strong>2026-09-24 由 60 → 120 → 180 秒</strong>），到点由微信自动停止，与手动停止走同一套收尾（用户想继续再点一次话筒）；<strong>它是&quot;单次回答允许说多久&quot;的产品口径</strong>，与后端&quot;物理连接绝对上限 300 秒&quot;是两个概念（见 §5.6 末尾）</td></tr><tr><td style="text-align:left;">到达单次上限</td><td style="text-align:left;">✅ <strong>已实现（2026-09-23）</strong>：由 <code>SpeechHandlers.onTimeout</code> 给显式提示（「本次语音输入已结束，可再次点话筒继续」）：静默停止会被当成&quot;识别坏了&quot;</td></tr></tbody></table><blockquote><p><strong>录音参数的官方依据</strong>（2026-09-24 核对微信开放文档 <code>RecorderManager.start</code>）：</p><ul><li><code>duration</code> 官方默认 <strong>60000</strong>、<strong>上限 600000（10 分钟）</strong> —— 原来的 60000 就是&quot;官方默认值&quot;， 现在的 <strong>180000</strong> 是产品口径（= 官方额度的 3/10），两者都不是&quot;规则上限&quot;；</li><li><code>frameSize</code>（单位 KB）官方注明<strong>传入才会有帧回调</strong>，且<strong>暂仅支持 mp3 / pcm</strong> —— 所以 <code>format: &#39;PCM&#39;</code> + <code>frameSize: 4</code> 不是可选优化，而是&quot;实时识别&quot;这条链路的<strong>硬前提</strong>；</li><li><code>sampleRate: 16000</code> 配 <code>encodeBitRate: 48000</code> 落在官方「采样率 × 编码码率」合法区间 （16000 → 24000~96000）内；官方原文明确<strong>不合法的组合会导致录音失败</strong> —— 改参数前先对表；</li><li>两处端/版本限制留意：<code>sampleRate</code> <strong>PC 不支持</strong>（微信 PC 版跑小程序时录音参数未必完整支持）； 官方另有 <code>audioMode: &#39;voiceRecognition&#39;</code>（基础库 3.17.3+，噪声抑制 + 自动增益）<strong>尚未启用</strong>， 若嘈杂环境识别率不理想可作为候选（需真机对比后再定）。</li></ul></blockquote><blockquote><p>停止识别时<strong>不立即释放通道</strong>：流式识别常在停止后才吐出最后一段定稿文本，因此留一个约 <strong>8 秒</strong>的空闲窗口 （<code>WsAsrTransport#stop()</code> 的 <code>IDLE_RELEASE_DELAY_MS</code>）再断开，避免最后一句丢失。 <strong>但不能无限期保留</strong>（2026-09-24 更正）：后端 <code>DoubaoAsrClient</code> 有静音保活，挂着的豆包会话会继续按 音频时长计费 —— 原注释里&quot;这条通道不计费、多留一会儿没有成本&quot;是<strong>错的</strong>；后端另有 25 秒上游空闲兜底 （见后端方案 §4.2.4）。</p><p>Hook 对外是 <code>{ listening, toggle, stop }</code>：<code>toggle</code> 给话筒按钮做&quot;开 / 关&quot;， <code>stop</code> 给「发送作答」这类<strong>必须停</strong>的场景调用 —— 它不做状态反转， 免得在竞态（刚点话筒、还在建连）时反而把识别开起来。</p><p><strong>入参 <code>enabled</code> / <code>terminated</code> 是资源生命周期的唯一开关</strong>（2026-09-24 加，见 §6.2 的「生命周期收口」）： 页面只回答&quot;现在还能不能录音&quot;，<strong>不直接操作 WebSocket</strong> —— &quot;什么时候真的断开连接&quot;只由 hook 决定。</p></blockquote><h2 id="_6-接口待接入清单" tabindex="-1"><a class="header-anchor" href="#_6-接口待接入清单"><span>6. 接口待接入清单</span></a></h2><h3 id="_6-1-会话与消息-本页面的核心缺口" tabindex="-1"><a class="header-anchor" href="#_6-1-会话与消息-本页面的核心缺口"><span>6.1 会话与消息（本页面的核心缺口）</span></a></h3><table><thead><tr><th style="text-align:left;">能力</th><th style="text-align:left;">建议形态</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">开场白</td><td style="text-align:left;">会话创建时后端下发第一题</td><td style="text-align:left;">✅ <strong>已落地（2026-09-23）</strong>：删掉了固定文案 <code>GREETING</code> —— 建连成功即起算，首问由后端下发（首条下行是 <code>THINKING</code>）</td></tr><tr><td style="text-align:left;">提交回答 + 收追问</td><td style="text-align:left;"><strong>走 <code>/ws/audio</code> 的 WS 上行</strong>：建连带 <code>input=text</code>（且 <code>mode=mock</code>），上行 <code>{&quot;type&quot;:&quot;ANSWER&quot;,&quot;text&quot;:&quot;...&quot;}</code>（<strong>不是流式 HTTP</strong>）。<strong>后端已可用</strong>（Step 1），协议已登记</td><td style="text-align:left;">下行沿用既有协议：先 <code>THINKING</code>、再 <code>LLM_REPLY</code> 流式分片（<code>final</code> 标记收尾，<code>replyId</code> <strong>由后端生成</strong>）。UI 侧仍是「用户气泡落地 → <code>loading</code> 占位 → 首字到达取消 → <code>error</code> 还原输入」</td></tr><tr><td style="text-align:left;">历史记录</td><td style="text-align:left;">复用 <code>/api/interviews/history</code> 与详情</td><td style="text-align:left;">文本版是否与语音版混在同一列表，需产品确认</td></tr></tbody></table><blockquote><p><strong>为什么不是流式 HTTP（2026-09-22 与后端方案对齐后修订）</strong>：会话计时、心跳、暂停恢复、顶号、余额下发 <strong>全在 WS 连接上</strong>，且逻辑会话与计费状态由 <code>InterviewSessionState</code> + <code>InterviewBillingService</code> 持有。 走 HTTP 等于把这三套在服务端再实现一遍；更关键的是 HTTP 无连接后&quot;连接失活判据&quot;直接失效 （后端方案原文见《模拟面试第二版-语音识别与LLM回合解耦方案》§4.1.3）。</p><p>因此：<strong><code>QnaChat.tsx</code> 只能借鉴它的 UI 侧模板</strong>（<code>loading</code> 占位 / 逐字填充 / 错误还原输入）， 传输层必须换成 WS 消息（<code>THINKING</code> / <code>LLM_REPLY</code>），<strong>不要照搬 <code>streamPost</code> 那套 <code>onMeta/onDelta/onDone/onError</code></strong>。</p></blockquote><p><strong>接线契约（引后端方案，别在这里另抄一份协议）</strong>：</p><ul><li><strong>建连</strong>：<code>input=text</code> 且 <code>mode=mock</code>。<code>assist + text</code> 不是合法组合，后端在建连阶段直接失败 （握手错误 <code>INTERVIEW_PREPARE_FAILED</code>）；页面入口的 <code>?mode=text</code> 不要透传（见 §4.1 的对照表）。</li><li><strong>上行</strong>：<code>{&quot;type&quot;:&quot;ANSWER&quot;,&quot;text&quot;:&quot;…&quot;}</code>。<strong>不做幂等、不要加 <code>answerId</code> / <code>clientMsgId</code></strong> —— 后端上行解析是严格的（<code>Jsons.parse</code> 默认遇到未知字段即失败），多一个字段会让<strong>整条作答被丢弃</strong>。 将来若要做&quot;失败重试&quot;，两端同版本一起加 <code>clientMsgId</code> 并由后端去重。</li><li><strong>前端先拦</strong>：非空 + 长度上限 <strong>2000 字</strong>（输入框 <code>maxLength</code>）。 否则后端会回 <code>INVALID_ANSWER</code> / <code>ANSWER_TOO_LONG</code> —— 白跑一次往返。</li><li><strong><code>TURN_BUSY</code> 是&quot;发送后禁用输入框&quot;的实现依据</strong>：首问或上一轮还在流式输出时，后端会拒绝本次作答。 页面应保持禁用 + 提示「AI 正在回复中」，等 <code>LLM_REPLY(final=true)</code> 再恢复输入。 <blockquote><p><strong><code>final</code> 分片就是流式响应的末分片，它带最后一段正文</strong>：收尾时仍按<strong>追加</strong>处理（<code>prev + text</code>）， <strong>不要</strong>改成&quot;用 final 的文本整段替换&quot;；一轮回复只应有一条 final 分片。 另注意字段名以实际 JSON 为准（是 <code>final</code>，不是 Java 侧的 <code>isFinal</code>）—— 判错会得出&quot;结束信号没来&quot;的假结论（后端方案 §12.6.1 记了这个坑）。</p></blockquote></li><li><strong><code>replyId</code> 由后端生成</strong>（文本作答没有 ASR id）：前端按 <code>onThinking(replyId)</code> 建占位气泡、 按 <code>LLM_REPLY.replyId</code> 填充，<strong>不要自己造 ID、也不依赖其格式</strong>。</li><li><strong>错误码已登记</strong>在 <code>features/interview/ws.ts</code>：<code>INVALID_INPUT_MODE</code> / <code>TURN_BUSY</code> / <code>INVALID_ANSWER</code> / <code>ANSWER_TOO_LONG</code>（均<strong>非终止性</strong>，不进 <code>FATAL_CODES</code>；<code>TURN_BUSY</code> 只是&quot;稍后再发&quot;）。</li><li><strong>就绪点</strong>：text 模式<strong>建连成功即起算</strong>，并且 MOCK 首问由后端<strong>立刻下发</strong>（首条下行是 <code>THINKING</code>）—— 所以页面不需要&quot;先发一句才激活&quot;，也不要用固定文案兜底开场白（接入后删掉 <code>GREETING</code>）。</li></ul><p><strong>落地记录（2026-09-23，<code>pages/mock-interview-v2/index.tsx</code>）</strong>：</p><table><thead><tr><th style="text-align:left;">要点</th><th style="text-align:left;">实现</th></tr></thead><tbody><tr><td style="text-align:left;">建连</td><td style="text-align:left;"><code>connect({ mode: &#39;mock&#39;, input: &#39;text&#39;, wsBaseUrl, language / detailLevel / interviewStyle（沿用设置页）, templateUid: getSelectedTemplate()?.uid })</code></td></tr><tr><td style="text-align:left;">首问</td><td style="text-align:left;"><strong>已删除固定开场白</strong>：建连成功即起算，首条下行就是后端下发的 <code>THINKING</code> + 追问（不再用 <code>GREETING</code> 兜底）</td></tr><tr><td style="text-align:left;">作答</td><td style="text-align:left;">乐观渲染用户气泡 → <code>sendAnswer(text)</code>；输入框 <code>maxLength=2000</code>，非空 / 超长在前端先拦</td></tr><tr><td style="text-align:left;">输入框禁用</td><td style="text-align:left;"><code>canAnswer = status===&#39;active&#39; &amp;&amp; !replying</code>；发送时置 <code>replying</code>，<code>onLlmDone</code> / 非终止性错误 / 会话结束时恢复（话筒按钮同样受它约束）</td></tr><tr><td style="text-align:left;">发送即结束语音输入</td><td style="text-align:left;"><code>handleSend</code> 校验通过后先调 <code>useSpeechInput</code> 的 <code>stop()</code> 再发送：输入框紧接着会被清空，识别结果再写回来就成了&quot;幽灵文字&quot;（细节见 §6.2 落地记录）</td></tr><tr><td style="text-align:left;">流式渲染</td><td style="text-align:left;"><code>onThinking(replyId)</code> 建占位气泡（typing 指示器）→ <code>onLlmDelta</code> 追加 → <code>onLlmDone</code> <strong>追加末分片正文</strong>并恢复输入（final 分片带正文，是追加语义）</td></tr><tr><td style="text-align:left;"><code>TURN_BUSY</code></td><td style="text-align:left;"><strong>收回</strong>那条未被接受的作答（删气泡 + 把文字还回输入框）<strong>并保持禁用</strong>，等当前这轮的 <code>final</code> 到了再让用户重发 —— 既守&quot;忙时不放行&quot;，也不让用户白写一段话</td></tr><tr><td style="text-align:left;">其他非终止性错误</td><td style="text-align:left;"><code>INVALID_ANSWER</code> / <code>ANSWER_TOO_LONG</code> 同样收回并还回输入框；<code>INVALID_INPUT_MODE</code> 属客户端配置错误，按结束处理</td></tr><tr><td style="text-align:left;">终止性错误</td><td style="text-align:left;"><code>AUTH_FAILED</code> / 余额类 / <code>HEARTBEAT_TIMEOUT</code> / <code>SESSION_REPLACED</code> → 收尾 + 在对话流里补一条<strong>错误气泡</strong>（用户回看时知道发生过什么）；余额类跳充值页（沿用 V1）</td></tr><tr><td style="text-align:left;">剩余时长</td><td style="text-align:left;"><code>onTimeUpdate</code> → 头部显示「剩余 mm:ss」（会话按时长计费，用户需要随时能看到）。服务端 <code>TIME_UPDATE</code> 只是<strong>间隔快照</strong>，照抄下来会一跳一跳，因此前端以「快照秒数 + 收到时刻」为基准（<code>timeSyncRef</code>）<strong>本地每秒递减</strong>，每条新快照重新对齐、避免误差累积；只在 <code>active</code> 时走秒（暂停即停表），离开进行中时把当前剩余<strong>定格</strong>为新基准，恢复时从定格值接着数，等新快照到了再按服务端口径对齐</td></tr><tr><td style="text-align:left;">看门狗（前端自加）</td><td style="text-align:left;">后端在 LLM 流式失败时<strong>不下发 ERROR</strong>（只落日志），前端会永久停在&quot;回复中&quot; → <strong>90 秒内一条下行消息都没有</strong>即恢复输入框。误判代价小（提前发送会被 <code>TURN_BUSY</code> 拒并回到禁用），漏判代价大（输入框卡死）</td></tr></tbody></table><blockquote><p>看门狗这条其实指向一个<strong>后端语义缺口</strong>：LLM 失败本该有一条明确的错误码，而不是让客户端靠静默超时猜。 本轮先在前端兜住，是否在后端补 <code>ERROR</code>（如 <code>LLM_FAILED</code>）尚未定 —— 记在<strong>待议</strong>，不在本方案强制范围。</p></blockquote><h3 id="_6-2-语音识别通道-第-5-节的-asrtransport-实现" tabindex="-1"><a class="header-anchor" href="#_6-2-语音识别通道-第-5-节的-asrtransport-实现"><span>6.2 语音识别通道（第 5 节的 <code>AsrTransport</code> 实现）</span></a></h3><p>无论走哪条路线（现在是 A），<code>AsrTransport</code> 对外都只产出 <code>SpeechResult{ text, final }</code>：</p><ul><li>方案 A：<code>start</code> 建连（带鉴权）→ <code>pushFrame</code> 推 16k/16bit/单声道 PCM → 回包按「中间态/定稿」分别 <code>onResult</code>。</li><li>方案 B：<code>start</code> 调插件开录 → 插件回调直接是文本。</li></ul><p><strong>方案 A 的落地状态（2026-09-22 第二次修订）</strong>：</p><blockquote><p>✅ <strong><code>/ws/asr</code> 后端侧已交付</strong>（后端方案 Step 2）：端点注册 / handler / 识别会话 / 轻量鉴权拦截器都齐了， 识别运行本体复用 <code>AsrStreamRunner</code>（P0-1 产物：重连预算、退避、残留帧丢弃、<code>asrId</code> 轮换）。 所以前端现在<strong>可以开始实现 <code>AsrTransport</code></strong>（不再是&quot;等接口&quot;）。</p></blockquote><p>实现时的三步 + 协议要点（<strong>事实以后端方案 §4.2.2 为准</strong>）：</p><ol><li><strong>点话筒才建连</strong>（带 ticket，走同一个 <code>GET /api/ws/ticket</code>）；停止识别后不必立刻断开 （等最后一次定稿文本），<code>dispose</code> 时释放 —— 与 5.3 一致；</li><li>推 PCM 帧（16kHz/16bit/单声道，与 <code>recorder.ts</code> 参数一致），按 <code>ASR_RESULT</code> 的 <strong><code>final</code></strong> 字段 分流中间态/定稿（<strong><code>final</code> 是 Step 2 新增的字段</strong>，两条通道都会带）；</li><li>记住这条通道<strong>物理上与面试会话无关</strong>：不计费、不触发 AI 回合、识别失败<strong>不会</strong>影响面试 （与 <code>/ws/audio</code> 的 <code>ASR_UNAVAILABLE</code> 杀会话完全不同）。但它的<strong>使用资格来自面试</strong> （后端方案 §4.2.5，✅ 已实现）：必须有进行中的面试才能建连，面试结束会被服务端<strong>静默回收</strong>。</li></ol><p><strong>实现 <code>AsrTransport</code> 时要一并做的两件事</strong>：</p><ul><li><strong>登记错误码</strong>（这条通道自己的语义空间，<strong>不要塞进 <code>ws.ts</code> 的面试错误码</strong>）： <code>AUTH_FAILED</code>(4001) / <code>ASR_LIMIT_EXCEEDED</code>(4004，先关掉自己那条旧识别连接再重试) / <code>ASR_QUOTA_EXCEEDED</code>(4006，今日次数已用完，<strong>重试无用</strong>、不要自动重连，提示改用打字) / <code>ASR_UNAVAILABLE</code>(4003，提示改用打字) / <code>ASR_TIMEOUT</code>(4005，当作&quot;本次语音输入已结束&quot;)； ✅ <strong><code>ASR_NO_ACTIVE_SESSION</code>(4007，2026-09-24 已登记)</strong>：没有进行中的面试，提示「请先开始面试」， <strong>不要自动重连</strong>（除非用户重新开始了一场面试）； 正常结束是 1000（含&quot;面试结束被服务端回收&quot;），静默收尾即可。 <blockquote><p>四道闸门顺序：凭证 → <strong>资格</strong> → 并发 → 日配额（后端已写死）。三者的引导各不相同： 资格是&quot;去开始面试&quot;、并发是&quot;先关掉旧连接&quot;（可即时自救）、配额是&quot;改用打字&quot;（重试无用）—— <strong>别合成一句提示</strong>。 4007 已进 <code>transport.ts</code> 的白名单与关闭码映射 —— <strong>不登记的话</strong>它会落进&quot;未知码 → <code>ASR_UNAVAILABLE</code>&quot; 兜底，把「去开始面试」说成「改用打字」（同一份代码里那个兜底是从第一版就有的）。</p></blockquote></li><li><strong>上行只发音频</strong>：这条通道没有心跳、没有控制指令（后端收到文本只记日志）； 连接存活由后端<strong>物理连接绝对上限</strong>兜底（<code>session-max-duration-ms</code>，<strong>300 秒</strong>，绝对墙钟、不重置）。 ⚠️ <strong>两个概念别混</strong>（2026-09-24 明确）：<strong>单次回答允许说多久</strong> = 前端录音上限（<code>duration: MAX_RECORDING_MS</code>，<strong>180 秒</strong>）； <strong>连接能活多久</strong> = 后端那个 300 秒（<strong>关系固定为「后端 = 前端 + 120 秒余量」</strong>）。后者只兜&quot;客户端该关没关 / 连接悬挂&quot;，正常路径由前端的 8 秒空闲释放先收掉。</li></ul><blockquote><p>后端侧对这条通道的禁区是<strong>硬约束</strong>（后端方案 §4.2.1）：<code>/ws/asr</code> 不接 <code>SessionRegistry</code>、 不走 <code>requestClose</code> / <code>cleanup</code>、不创建/修改 <code>Interview</code>、不计费、不落库、不触发 LLM； 自检句是「<strong>识别失败时会不会有人想动面试状态？</strong>」—— 答案是&quot;不会&quot;才没跑偏。 前端侧同构的一条：<strong>识别失败只提示&quot;改用打字&quot;，不要因此去动面试连接</strong>。</p></blockquote><p><strong>落地记录（2026-09-23，<code>features/speech/transport.ts</code> + <code>recognizer.ts</code>）</strong>：</p><table><thead><tr><th style="text-align:left;">要点</th><th style="text-align:left;">实现</th></tr></thead><tbody><tr><td style="text-align:left;">建连</td><td style="text-align:left;"><code>start()</code> 取 ticket（<code>GET /api/ws/ticket</code>，<strong>各自取各自的</strong>：一次性消费）→ 连 <code>/ws/asr?ticket=</code> → 等 <code>onOpen</code> 才算成功</td></tr><tr><td style="text-align:left;">接口签名</td><td style="text-align:left;"><code>AsrTransport.start()</code> 从&quot;同步抛错&quot;改为<strong>返回 Promise</strong>（建连本就是异步的，只有它能表达&quot;通道没建起来&quot;）；<code>SpeechRecognizer.start()</code> 随之改异步</td></tr><tr><td style="text-align:left;"><strong>先建连、后开录音</strong></td><td style="text-align:left;">凭证失效 / 并发超限 / 配额用完时<strong>根本不打开麦克风</strong> —— 否则会出现&quot;录音在跑、识别通道没有出口&quot;（麦克风常亮，用户以为在识别）</td></tr><tr><td style="text-align:left;">下行结果</td><td style="text-align:left;"><code>ASR_RESULT{ text, final }</code> → <code>SpeechResult</code>（<strong><code>final</code> 与 <code>isFinal</code> 两种字段名都认</strong>，见后端方案 §12.6.1）</td></tr><tr><td style="text-align:left;">错误码</td><td style="text-align:left;">按通道语义空间映射为用户文案（<code>AUTH_FAILED</code> / <code>ASR_LIMIT_EXCEEDED</code> / <code>ASR_QUOTA_EXCEEDED</code> / <code>ASR_UNAVAILABLE</code> / <code>ASR_TIMEOUT</code>），<strong>没有塞进 <code>ws.ts</code> 的面试错误码</strong>；并发与配额<strong>分开提示</strong>（一个能自救、一个重试无用）</td></tr><tr><td style="text-align:left;">关闭码</td><td style="text-align:left;"><code>1000</code> 静默收尾；<strong><code>4005</code>（时长上限）在已停止推帧时按正常结束处理</strong>（用户早就说完了，不该弹&quot;出错了&quot;）；其余按原因提示</td></tr><tr><td style="text-align:left;"><code>stop()</code> 不立即断开</td><td style="text-align:left;">流式识别可能在停止后才吐最后一段定稿文本 → <strong>空闲 ~8 秒后自动断开</strong>（<code>IDLE_RELEASE_DELAY_MS</code>；<code>start()</code>/<code>dispose()</code> 都会清掉那个定时器）。原来说&quot;这条通道不计费、多留一会儿没有成本&quot;是错的：后端静音保活会让挂着的豆包会话继续按时长计费</td></tr><tr><td style="text-align:left;"><code>stop()</code> 的两种时机</td><td style="text-align:left;">① <strong>识别中</strong>（<code>active</code>）→ 停录音 + 通知页面；② <strong>建连中</strong>（<code>starting</code>，麦克风还没打开）→ 只置 <code>canceled</code>，建连完成即释放通道、<strong>不打开麦克风</strong>（此时没触发过 <code>onStart</code>，因此不回调 <code>onStop</code>）。②是&quot;点话筒后立刻点发送&quot;的兜底：没有它，那次识别会先建连、后开麦，用户明明已经发出去了</td></tr><tr><td style="text-align:left;">服务端主动结束</td><td style="text-align:left;">识别器<strong>先把录音管理器停掉</strong>再通知页面：避免&quot;识别通道已经没了、麦克风还在采集&quot;（既是隐私问题也白耗电）</td></tr></tbody></table><p><strong>生命周期收口（2026-09-24，<code>useSpeechInput</code> + 页面只多传一个判据）</strong>：</p><p>起因是一个<strong>前端资源生命周期 bug</strong>（与后端无关）：<code>transport.stop()</code> 的语义是&quot;停推帧、<strong>保留连接</strong>&quot;， 而页面在会话结束时没有任何地方去 <code>dispose()</code>，于是：</p><table><thead><tr><th style="text-align:left;">现象</th><th style="text-align:left;">之前</th><th style="text-align:left;">现在</th></tr></thead><tbody><tr><td style="text-align:left;">面试结束（掉线 / 余额耗尽 / 主动结束）</td><td style="text-align:left;">识别连接残留到后端 300 秒上限；话筒按钮已被禁用，<strong>用户关不掉</strong>；&quot;正在聆听…&quot;还挂在已结束的页面上</td><td style="text-align:left;"><code>terminated=true</code> → <code>dispose()</code> 立即关闭；<code>listening</code> 归位</td></tr><tr><td style="text-align:left;">暂停 / 恢复</td><td style="text-align:left;"><code>listening</code> 卡在 <code>true</code>，恢复后点话筒<strong>反而把识别停掉</strong>（要点两次才真的开始）</td><td style="text-align:left;"><code>enabled=false</code> → <code>stop()</code> + <code>listening=false</code>；恢复后点话筒正常开始</td></tr><tr><td style="text-align:left;">发送后迟到的定稿片段</td><td style="text-align:left;">写回刚清空的输入框（幽灵文字）</td><td style="text-align:left;">生命周期闸门丢弃</td></tr><tr><td style="text-align:left;">结束后迟到的失败通知 / 超时提示</td><td style="text-align:left;">在已结束的页面上弹 toast</td><td style="text-align:left;">丢弃</td></tr><tr><td style="text-align:left;"><strong>停止说话后连接一直挂着</strong>（2026-09-24 补）</td><td style="text-align:left;"><code>stop()</code> 只停推帧，连接留到下一次点话筒 / 页面卸载 —— 期间豆包会话靠静音保活一直活着（<strong>静音帧同样按时长计费</strong>），最长到后端 300 秒</td><td style="text-align:left;"><code>WsAsrTransport#stop()</code> 起 <strong>8 秒空闲定时器</strong>：到点仍没再 <code>start()</code> 就 <code>dispose()</code>（尾包照样落地）</td></tr><tr><td style="text-align:left;"><strong>客户端该关却没关</strong>（崩溃 / 老版本 / 小程序切后台定时器不跑）</td><td style="text-align:left;">连接挂到 300 秒上限，豆包侧一直在喂静音；并发闸门也被占着</td><td style="text-align:left;">后端 <strong>25 秒</strong>上游空闲兜底（<strong>只对 <code>/ws/asr</code></strong>，见后端方案 §4.2.4）：静默关闭（1000、无 ERROR），指标 tag <code>input_idle</code></td></tr></tbody></table><p>实现要点（三条，改代码前先看）：</p><ol><li><strong>两个入参的语义</strong>：<code>enabled</code> = &quot;现在能不能录音&quot;（暂停 / AI 生成中 / 未就绪都是 <code>false</code>）， <code>terminated</code> = &quot;是否彻底不需要识别通道&quot;（<strong>只有面试结束才为 <code>true</code></strong>）。页面传的是 <code>enabled: canAnswer</code>、<code>terminated: status === &#39;ended&#39;</code> —— 与输入框 / 话筒 / 发送按钮<strong>共用同一个判据</strong>， 避免&quot;按钮说不能用、hook 却还活着&quot;这类漂移。</li><li><strong>闸门在渲染期同步赋值</strong>（<code>enabledRef.current = enabled</code>），不走 effect： 识别回调可能在任意时刻到达，用 effect 会留下&quot;状态已变、effect 还没跑&quot;的一帧窗口。</li><li><strong><code>stop()</code> 里也要显式 <code>setListening(false)</code></strong>：识别器在&quot;建连中被要求停止&quot;那条分支不会回调 <code>onStop</code>。</li></ol><blockquote><p><code>enabled</code> 用的是 <code>canAnswer</code>（= <code>status === &#39;active&#39; &amp;&amp; !replying</code>）而不是单纯的 <code>status === &#39;active&#39;</code> —— 多排除&quot;AI 正在回复&quot;这一档，顺带把上表第 3 行（发送后迟到定稿写回输入框）也一起堵住。</p><p>✅ <strong>已接（2026-09-24）</strong>：<code>ASR_NO_ACTIVE_SESSION</code>(4007) 已登记进 <code>features/speech/transport.ts</code> （错误码白名单 + 关闭码映射 + 文案「请先开始面试」），不会落进 <code>ASR_UNAVAILABLE</code> 的兜底。</p><p>另外前端这套收口与后端 Step 4 是<strong>互补</strong>的、不是替代关系：前端负责&quot;面试结束就自己释放&quot;， 后端负责&quot;面试结束就把服务端这条连接收掉&quot; —— 两边幂等，谁先到都不会报错。</p></blockquote><h3 id="_6-3-会话生命周期-接入时必须一起解决-不能只接-发消息" tabindex="-1"><a class="header-anchor" href="#_6-3-会话生命周期-接入时必须一起解决-不能只接-发消息"><span>6.3 会话生命周期（接入时必须一起解决，不能只接&quot;发消息&quot;）</span></a></h3><p>V2 只是把上行从音频换成文本，<strong>产品语义仍是一场有时长的面试</strong>。 下表区分&quot;后端已实现（直接消费）&quot;与&quot;仍待产品定&quot;：</p><table><thead><tr><th style="text-align:left;">机制</th><th style="text-align:left;">状态与做法</th></tr></thead><tbody><tr><td style="text-align:left;">建会话与结束</td><td style="text-align:left;">✅ 已实现（后端 + 前端）：<strong>建连成功即起算</strong>（text 模式不再等 ASR 就绪），MOCK 首问由后端立刻下发；结束时生成面试记录。前端收尾见 §6.3.3：头部「结束」→ 用通用模板进「体验完成」，否则返回上一页</td></tr><tr><td style="text-align:left;">计时与计费</td><td style="text-align:left;">✅ 后端已实现：<strong>文本模式同样按会话时长计费</strong>（思考时间算面试时间），且<strong>不做&quot;无操作自动暂停&quot;</strong>（已定稿）。「文本模式单价是否与语音一致」仍属商业决策（见 §9-3）</td></tr><tr><td style="text-align:left;">心跳</td><td style="text-align:left;">⚠️ <strong>硬要求</strong>：建连后立即发一次 <code>{&quot;type&quot;:&quot;heartbeat&quot;}</code>，之后<strong>每 25 秒一次</strong>，随连接启停。文本模式下「思考 1 分钟再回」是常态，心跳比语音模式更关键（小程序 V1 的 <code>InterviewSocket</code> 已内置，V2 复用它即可，页面<strong>不要自己 setInterval</strong>）。<strong>失联阈值</strong>：语音 60 秒 / 文字作答 <strong>180 秒</strong>（<code>realtime.text-heartbeat-timeout-ms</code>，见 §6.3.1）</td></tr><tr><td style="text-align:left;">暂停 / 恢复</td><td style="text-align:left;">✅ 后端已实现：显式 <code>PAUSE</code> → <code>PAUSED</code>，用 <code>resume=&lt;逻辑会话ID&gt;</code> 重连，重连后<strong>仍是 text</strong>（<code>input_mode</code> 已落库还原）。<br>✅ <strong>前端入口已实现（2026-09-23）</strong>：头部「暂停」（带确认弹窗）→ 暂停条 + 「继续面试」，<strong>头部同一位置也变为「继续」</strong>（两处等价，都是 <code>handleResume</code>）；时序与守卫见 §6.3.2</td></tr><tr><td style="text-align:left;">多端顶号</td><td style="text-align:left;">✅ 沿用 V1：同一用户新建连接会踢掉旧连接</td></tr><tr><td style="text-align:left;">计费活跃度判据</td><td style="text-align:left;">✅ <strong>不沿用&quot;无音频即静默&quot;</strong>：只看心跳。后端<strong>不做「收到 <code>ANSWER</code> 就当心跳」的特例</strong>（那样&quot;正在思考&quot;与&quot;已掉线&quot;无法区分）—— 这正是心跳是硬要求的原因</td></tr><tr><td style="text-align:left;">失联 vs 暂停</td><td style="text-align:left;">⚠️ <strong>失联 = 结束，显式 <code>PAUSE</code> = 暂停</strong> —— 见 §6.3.1，这条最容易被当成 bug</td></tr></tbody></table><h4 id="_6-3-1-两条状态机-分开写-别合并-三条容易混的语义" tabindex="-1"><a class="header-anchor" href="#_6-3-1-两条状态机-分开写-别合并-三条容易混的语义"><span>6.3.1 两条状态机（分开写，别合并）+ 三条容易混的语义</span></a></h4><p><strong>① 后端权威的会话状态</strong>（前端只消费，不定义）：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>pending ──(WebSocket 建连)──→ active ──(显式 PAUSE)──→ paused ──(resume=逻辑会话ID)──→ active</span></span>
<span class="line"><span>                                │                        │</span></span>
<span class="line"><span>                                └──── 结束 / 失联 / 余额耗尽 / 暂停超时 ────→ ended</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>（这是 <code>interview.status</code> 的取值；内存里的逻辑会话只有 <code>ACTIVE</code> / <code>PAUSED</code> / <code>ENDED</code> 三态， <code>pending</code> 只存在于&quot;准备好了但还没建连&quot;这个短暂窗口。）</p></blockquote><p><strong>② 前端回答气泡的 UI 状态</strong>（与上面的会话状态<strong>无关</strong>）：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>sending ──→ thinking ──→ streaming ──→ done</span></span>
<span class="line"><span>                 │             │</span></span>
<span class="line"><span>                 └─────────────┴──→ error（还原输入框 / 提示）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>由后端事件驱动：<code>THINKING</code> → <code>thinking</code>；<code>LLM_REPLY(final=false)</code> → <code>streaming</code> 并追加文本； <code>LLM_REPLY(final=true)</code> → <code>done</code>（<strong>末分片带最后一段正文，仍按追加处理</strong>）；<code>ERROR</code> 或本地失败 → <code>error</code>。</li><li><strong>不要把 <code>thinking</code> / <code>streaming</code> 画进会话状态机</strong> —— 它们只是&quot;这一个气泡&quot;的状态， 期间会话一直是 <code>active</code>（回合执行状态由后端 <code>ConversationTurnRunner</code> 自持，前端不参与）。</li></ul><p><strong>三条容易混的语义（写死）</strong>：</p><table><thead><tr><th style="text-align:left;">事件</th><th style="text-align:left;">会话状态</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">用户在思考，长时间不发 <code>ANSWER</code></td><td style="text-align:left;">仍 <code>active</code></td><td style="text-align:left;"><strong>思考 ≠ 暂停</strong>；思考时间算面试时间（按整场时长计费）</td></tr><tr><td style="text-align:left;">发 <code>{&quot;type&quot;:&quot;heartbeat&quot;}</code></td><td style="text-align:left;">仍 <code>active</code></td><td style="text-align:left;">心跳只证明<strong>连接活着</strong>，不代表&quot;用户正在操作&quot;，也不刷新计费活跃度</td></tr><tr><td style="text-align:left;">超过失联阈值没收到心跳（语音 60 秒 / <strong>文字作答 180 秒</strong>）</td><td style="text-align:left;"><code>ended</code></td><td style="text-align:left;"><strong>失联 = 结束，不是暂停</strong>（后端踢出 + 停计费 + 落库收尾）；只有显式 <code>PAUSE</code> 才进 <code>paused</code>。文字模式阈值放宽的理由见下</td></tr><tr><td style="text-align:left;">显式 <code>PAUSE</code> 后</td><td style="text-align:left;"><code>paused</code></td><td style="text-align:left;">保留 15 分钟等 <code>resume</code> 重连，超时 <code>SESSION_EXPIRED</code> 结束</td></tr></tbody></table><blockquote><p><strong>已定稿（2026-09-22，产品方向）：失联仍沿用「结束」，不改「暂停」；但文字作答的失联阈值放宽到 180 秒。</strong> 这样两套语义都保持干净：</p><table><thead><tr><th style="text-align:left;">事件</th><th style="text-align:left;">含义</th><th style="text-align:left;">处置</th></tr></thead><tbody><tr><td style="text-align:left;">显式 <code>PAUSE</code></td><td style="text-align:left;"><strong>用户明确表示&quot;我暂时不面了&quot;</strong></td><td style="text-align:left;"><code>paused</code>，15 分钟内可 <code>resume</code></td></tr><tr><td style="text-align:left;">失联（心跳丢失）</td><td style="text-align:left;"><strong>系统无法确认用户还在</strong></td><td style="text-align:left;">短暂等待后仍然 <code>ended</code>（停计费 + 落库收尾）</td></tr></tbody></table><p><strong>为什么不能把失联也映射成 <code>paused</code></strong>：那样 <code>paused</code> 会同时表示&quot;用户主动暂停 / 锁屏 / 断网 / 杀进程 / 故意断网&quot;五种情况，而「用户主动暂停」这条最有产品价值的信号会被冲掉 —— 一旦 <code>paused</code> 变成万能状态，它就不再能回答&quot;用户是不是自己要停&quot;。</p><p><strong>180 秒这个数的边界</strong>：失联判定期间会话仍是 <code>active</code>、<strong>仍在计时计费</strong>（心跳丢失 ≠ 暂停， 见 §6.3 表格），所以阈值 = &quot;真的一去不回时最多多扣多少秒余额&quot;；上限由它约束，不能随意放大。</p><p><strong>为什么不新增 <code>DISCONNECTED</code> 状态 / &quot;短暂重连窗口&quot;</strong>：小程序切后台时<strong>TCP 连接通常还在</strong> （被挂起的是 JS，心跳随之停），因此<strong>只放宽阈值</strong>就能让用户回来自动续上，<strong>零前端改动</strong>； 而连接真的断了（进程被杀 / 网络断开）时，前端<strong>没有自动重连</strong>（当前唯一的恢复路径是 &quot;显式 <code>PAUSE</code> → 手动 <code>resume</code>&quot;），后端留多久都不会有人来接 —— 要做真正的&quot;失联可恢复&quot;， 得引入新状态 + DB 语义 + 前端自动 resume，属独立议题，收益远小于成本。 <strong>结论：本轮只放宽阈值，不新增状态。</strong></p><p>联调提醒仍适用：若用户切后台<strong>超过 180 秒</strong>，回来时面试<strong>已经结束</strong>（不是暂停）， 这是既定行为，不要当 bug 报。</p><p><strong>已定稿（2026-09-23，后端已落地）</strong>：失联结束不再记 <code>USER_ENDED</code> —— 新增 <code>InterviewEndReason.DISCONNECTED</code>（心跳超时 / 顶号 / 传输错误），埋点 <code>end_reason</code> 从此能区分 「用户主动结束」与「连接层失联」；<strong>历史数据不回溯</strong>，报表按发布日分界。 映射与理由见后端方案 §8 P0-2 与 §8.1。</p></blockquote><h4 id="_6-3-2-暂停-恢复的时序与守卫-实现里最容易写错的一处" tabindex="-1"><a class="header-anchor" href="#_6-3-2-暂停-恢复的时序与守卫-实现里最容易写错的一处"><span>6.3.2 暂停 / 恢复的时序与守卫（实现里最容易写错的一处）</span></a></h4><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>点「暂停」</span></span>
<span class="line"><span>   ├─ 确认弹窗（取消则什么都不做）</span></span>
<span class="line"><span>   ├─ pausing = true  ←── 先立标志，再发指令</span></span>
<span class="line"><span>   └─ 上行 PAUSE</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>   服务端：回 PAUSED{sessionId}  → 页面：paused = true、存 sessionId、进入暂停态</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>   服务端：**正常关闭**物理连接（1000）→ onClose 一样会触发</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>   点「继续面试」（或头部「继续」，两处等价）→ connect({ ...原建连参数, resume: sessionId })</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>   恢复成功（onOpen）→ pausing / paused 复位 → 回到进行中（**不重发首问**）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>三条&quot;不这么写就会出 bug&quot;的实现要点：</p><ol><li><strong>必须用 <code>pausing</code> / <code>paused</code> 标志区分「预期的关闭」与掉线</strong>：服务端确认暂停后会正常关闭连接， <code>onClose</code> 照样触发。没有标志，页面会立刻弹&quot;连接已断开&quot;，用户以为暂停失败了。 <ul><li>已确认暂停（<code>paused</code>）→ 连接关闭<strong>静默处理</strong>；</li><li>发过 <code>PAUSE</code> 但没等到 <code>PAUSED</code> → 拿不到逻辑会话 ID，<strong>恢复不了</strong> → 按「暂停失败，请重新进入」收尾（<strong>不假装成功</strong>，否则用户点&quot;继续&quot;必然失败）。</li></ul></li><li><strong>恢复要用同一套建连参数</strong>（模式 / 作答方式 / 模板 / 语言…）+ 多一个 <code>resume</code>： 少任何一项，恢复出来的都是&quot;另一场面试&quot;（例如 <code>input</code> 丢了就退回 audio 会话）。 实现里存了一份建连参数（<code>wsConfigRef</code>）供恢复复用。</li><li><strong>暂停要 5 秒兜底</strong>：<code>PAUSED</code> 没来（发送时连接已关 / 网络断）时回滚标志并提示， 否则页面会永久停在&quot;正在暂停…&quot;。</li></ol><blockquote><p><strong>暂停会取消在途回复</strong>：如果在&quot;刚发完作答、AI 正在生成&quot;时暂停，那一轮回答会被服务端取消且不落库。 当前实现<strong>不阻止</strong>这种暂停（用户可能正是因为来电话才急着暂停），但没有把它做成&quot;无损暂停&quot; —— 真要无损，需要后端先把已生成的部分落库，属独立议题。</p><p><strong>参数名陷阱</strong>：恢复用的 query 参数是 <code>resume</code>（= <strong>逻辑会话 ID</strong>）；协议里另有一个 <code>resumeId</code> 是<strong>简历 ID</strong>。两者只差两个字母，混用会得到&quot;用错简历（或直接失败）的一场面试&quot;。</p></blockquote><h4 id="_6-3-3-结束与收尾跳转-对齐-v1" tabindex="-1"><a class="header-anchor" href="#_6-3-3-结束与收尾跳转-对齐-v1"><span>6.3.3 结束与收尾跳转（对齐 V1）</span></a></h4><p>入口在<strong>头部右侧</strong>（2026-09-23 由底部上移，红胶囊，与「暂停 / 继续」并列）：红胶囊按钮 → 断开连接（服务端据此收尾落库）→ 提示「面试已结束」→ <strong>600ms 后</strong>跳转：</p><blockquote><p>为什么从底部移到头部：底部只留输入区，操作入口集中在一处（V1 的底部按钮是当时的形态， 上移后与「暂停 / 继续」同一视线高度，不会在长对话里被滑走的输入区挤走）。 跳转规则、<code>usedTemplateRef</code> 定格、无二次确认这些都不随位置变化。</p></blockquote><table><thead><tr><th style="text-align:left;">本场面试</th><th style="text-align:left;">跳转</th><th style="text-align:left;">为什么</th></tr></thead><tbody><tr><td style="text-align:left;">用了<strong>通用模板</strong></td><td style="text-align:left;"><code>redirectTo(&#39;/pages/experience-complete/index&#39;)</code></td><td style="text-align:left;">体验用户还没填自己的岗位/简历，收尾正是引导补齐的最佳时机</td></tr><tr><td style="text-align:left;">没用模板</td><td style="text-align:left;">有上一页 → <code>navigateBack()</code>；否则 → <code>redirectTo(&#39;/pages/index/index&#39;)</code></td><td style="text-align:left;">回到设置页 / 首页即可</td></tr></tbody></table><p>三条要点：</p><ol><li><strong>模板分支用 <code>redirectTo</code> 而不是 <code>navigateBack</code></strong>：面试页要被顶掉 —— 返回它只会看到一张过期的对话。</li><li><strong>「是否用了模板」在建连成功时定格</strong>（<code>usedTemplateRef</code>）：面试结束后用户可能已经清掉选中态， 那时再读 storage 就判断不出这场面试到底用的什么（V1 同款处理）。</li><li><strong>不做二次确认、也不依赖网络往返</strong>：断连即结束，离线也点得动（与 V1 一致）。</li></ol><blockquote><p><strong>暂停态也能结束，但这条路径靠后端兜底</strong>：暂停时没有物理连接可断，服务端无从立刻得知&quot;用户结束了&quot;， 该记录由<strong>暂停保留时长</strong>（默认 15 分钟）到期后自动收尾 —— 也就是说这条路径的 <code>end_reason</code> 会是超时口径，而不是 <code>USER_ENDED</code>。要做到&quot;暂停态结束也立即落库、归因准确&quot;，需要一个显式的结束指令 （控制消息或 REST 接口），属独立议题（当前把它当已知限制）。</p></blockquote><h3 id="_6-4-埋点" tabindex="-1"><a class="header-anchor" href="#_6-4-埋点"><span>6.4 埋点</span></a></h3><p>本次只接 <code>page_view</code>（页面名「模拟面试-文字版」）。发送回答、语音输入等事件名需与 analytics 事件表对齐后再加，<strong>不上报回答原文，只上报长度</strong>（与 <code>ai_question_ask</code> 的隐私口径一致）。</p><h2 id="_7-文件清单" tabindex="-1"><a class="header-anchor" href="#_7-文件清单"><span>7. 文件清单</span></a></h2><blockquote><p>✅ <strong>2026-09-23：这些文件已在 <code>frontend-mp</code> 分支上</strong>（提交 <code>fc6504ef</code> 把原先 <code>stash@{0}</code> 里的页面与 <code>features/speech</code> 落了盘）。 本节保留为「文件在哪、为什么这么放」的索引；接线与传输层的实际实现见 §6.1 / §6.2 的<strong>落地记录</strong>。</p></blockquote><p>新增（代码在 <code>stash@{0}</code>）：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>src/pages/mock-interview-v2/index.tsx         # V2 页面：对话 + 输入区 + 话筒</span></span>
<span class="line"><span>src/pages/mock-interview-v2/index.config.ts   # 导航栏标题「模拟面试」</span></span>
<span class="line"><span>src/pages/mock-interview-v2/index.scss</span></span>
<span class="line"><span>src/features/speech/types.ts                  # SpeechResult / SpeechHandlers / SpeechError</span></span>
<span class="line"><span>src/features/speech/transport.ts              # AsrTransport 接口 + 待接入占位实现（唯一接入点）</span></span>
<span class="line"><span>src/features/speech/recognizer.ts             # SpeechRecognizer：采集 + 生命周期 + 错误归一</span></span>
<span class="line"><span>src/features/speech/hooks/useSpeechInput.ts   # 权限、文本合并规则、卸载释放</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>修改：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>src/app.config.ts                          # 注册 pages/mock-interview-v2/index（在 stash 里）</span></span>
<span class="line"><span>src/pages/mock-interview-setting/index.tsx # 支持 ?mode=text 路由到 V2，默认仍 V1（在 stash 里）</span></span>
<span class="line"><span>src/pages/demo/main/index.tsx              # 开发期直达入口（该文件 skip-worktree，不进提交）</span></span>
<span class="line"><span>src/features/interview/ws.ts               # ✅ 已落地：V2 协议登记（input 建连参数 + sendAnswer + 4 个错误码，纯增量）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>为什么不放在 <code>features/interview/</code>：语音输入是<strong>与面试链路无耦合的通用能力</strong>（不碰会话、计费、AI 回复）， 独立成 <code>features/speech/</code> 便于后续 AI 问答、简历诊断等场景直接复用；同时避免动到 V1 依赖的 <code>recorder.ts</code>。</p></blockquote><h2 id="_8-验证方式" tabindex="-1"><a class="header-anchor" href="#_8-验证方式"><span>8. 验证方式</span></a></h2><ol><li>微信开发者工具打开 demo 页（开发环境下自动登录）→ 点「模拟面试V2（文字作答）」，或走「模拟面试设置（V2 入口）」→ 自动建连。</li><li><strong>首问</strong>：建连成功后<strong>无需任何操作</strong>，AI 面试官主动发出第一题（先出现打字指示器气泡，再逐字填充）。 <strong>不应出现前端写的固定开场白</strong>（<code>GREETING</code> 已删）。</li><li><strong>作答</strong>：输入文字 → 发送 → 用户气泡立刻出现、输入框清空并<strong>禁用</strong>（话筒按钮同时禁用）→ AI 追问逐字填充 → 收到结束信号后输入框恢复。</li><li><strong>发送前拦截</strong>：空文本时发送按钮置灰；超过 2000 字被输入框 <code>maxLength</code> 拦住（后端仍会兜底拒绝）。</li><li><strong>重复发送</strong>：AI 生成期间输入框是禁用的（这是 <code>TURN_BUSY</code> 的语义要求）。若通过看门狗恢复后提前发送而被后端拒绝， 应看到「AI 正在回复中」提示，且<strong>刚才那段文字回到输入框</strong>（不会被丢掉）。</li><li><strong>语音输入</strong>：点话筒 → 首次弹麦克风授权 → 授权后话筒变红 + 出现「正在聆听」提示条 → 说话内容实时填入输入框 （中间态覆盖草稿、定稿追加）→ 再点一次结束。<strong>识别不会触发 AI 回答</strong>（这是本方案的核心解耦）。 <strong>识别中点发送</strong>：识别随发送一起停止（话筒恢复蓝色、状态条消失），发送后<strong>不应</strong>再有识别文字写回刚被清空的输入框。</li><li><strong>语音输入边界</strong>：说到 <strong>180 秒</strong>被自动停止 → 提示「已到单次语音上限，可再点话筒继续说」； 配额用完 → 「今日语音识别次数已用完，请改用打字输入」；已有识别在进行 → 「已有一条语音识别在进行，请稍后再试」。</li><li><strong>暂停 / 继续</strong>：点头部「暂停」→ 确认 → 输入区禁用、底部出现「面试已暂停，15 分钟内可继续」+「继续面试」， 且<strong>头部同一位置的按钮由「暂停」变为「继续」</strong>（两处都能恢复）； <strong>不应</strong>出现&quot;连接已断开&quot;之类的提示（服务端此时会正常关闭连接，页面已按预期关闭处理）， 也<strong>不应</strong>在对话流里多出一条&quot;面试已暂停&quot;的消息（暂停是状态，不是对话内容）。 点「继续面试」或头部「继续」→ 回到进行中，<strong>对话不丢、且不会重发首问</strong>。 暂停期间<strong>剩余时长停表</strong>（数字不再变化），恢复后接着走。</li><li><strong>暂停的边界</strong>：确认弹窗点取消 → 什么都不该发生（仍可正常作答）； 暂停超过 15 分钟（或后端把该记录结束掉）后再点「继续面试」→ 提示「暂停会话已失效，请重新开始面试」， 页面进入结束态（<strong>不能</strong>停在&quot;正在恢复面试…&quot;）。</li><li><strong>剩余时长</strong>：头部「剩余 mm:ss」<strong>按秒连续变化</strong>（不是几秒一跳），与服务端下发的快照误差不超过 1 秒。</li><li><strong>结束与收尾跳转</strong>：点头部「结束」→ 提示「面试已结束」→ 用通用模板的面试进入「体验完成」页 （没用模板则返回上一页）；模板分支用的是 <code>redirectTo</code>，所以<strong>返回键不该再回到面试页</strong>。</li><li><strong>H5 端</strong>（<code>pnpm dev:h5</code>）：点话筒提示「当前端暂不支持实时语音识别」，文字作答链路正常。</li><li><strong>构建</strong>：<code>pnpm build:weapp</code> 通过。</li><li><strong>V1 回归</strong>：V1 页面 <code>pages/mock-interview/index</code> 建连、心跳、暂停/恢复照旧（协议登记是纯增量，不改 V1 行为）。</li><li><strong>端到端</strong>：后端冒烟脚本 <code>pass-up.backend/scripts/smoke-v2.mjs</code> 全绿（协议层），与本页人工验收互为补充 （清单见《模拟面试第二版-联调与冒烟清单》）。</li><li><strong>输入区热区</strong>（改动后回归）：点输入胶囊最左侧留白 → <strong>输入框获得焦点</strong>； 点话筒 / 发送圆形的边缘与外围留白 → 仍然触发对应按钮（视觉圆形与热区不是同一层）。</li><li><strong>识别通道的生命周期收口</strong>（2026-09-24 新增）： <ul><li>说话中直接点「结束」→ 识别连接立即关闭（&quot;正在聆听&quot;提示消失、麦克风释放）， 且<strong>已结束的页面上不再出现任何识别 / 超时 Toast</strong>；</li><li>说话中「暂停」→ 录音停止、话筒恢复蓝色；「继续」后再点话筒能正常开始 （不能出现&quot;点了没反应&quot;或&quot;点了反而停&quot;）；</li><li>识别中点「发送」→ 发送后<strong>不应</strong>再有识别文字写回刚被清空的输入框。</li></ul></li><li><strong>资格闸门</strong>（2026-09-24 可测）：未开始 / 已结束 / 暂停中的页面上点话筒 → 提示「请先开始面试」， 且<strong>不会</strong>打开麦克风、不会自动重连；面试结束（含掉线 / 余额耗尽）时服务端会<strong>回收</strong>识别连接， 前端不应对这次关闭弹任何错误（此时本就在结束态）。</li><li><strong>停止后的空闲释放</strong>（2026-09-24 新增）： <ul><li>说一段话 → 点话筒停止 → 之后什么也不做：<strong>约 8 秒后</strong>连接自动关闭（开发者工具 Network 能看到 WS 关闭）， 再次点话筒能正常建立新连接；</li><li>「发送」后再点话筒仍然正常（发送那次 <code>stop()</code> 起的定时器<strong>不能</strong>把新连接关掉）；</li><li>把前端窗口临时调大（或用老版本客户端）以触发后端兜底：应看到 <code>[识别通道] 上游输入空闲已达上限</code> 与指标 <code>end=&quot;input_idle&quot;</code>，且页面<strong>不弹任何错误</strong>。</li></ul></li><li><strong>单次上限 180 秒</strong>（2026-09-24 新增，配合上限 60 → 120 → 180 秒）： <ul><li>说到 180 秒 → 微信自动停录音 + toast「已到单次语音上限，可再点话筒继续说」， <strong>已识别的文字留在输入框里</strong>（不能因为自动停止而丢掉）；</li><li>随后再点话筒 → 能正常开始新的一次（新连接、新的 180 秒窗口）；</li><li>界面<strong>不显示</strong>已用时长（2026-09-24 决定，见 §5.6 的权限/边界表）。</li></ul></li></ol><h2 id="_9-待确认问题" tabindex="-1"><a class="header-anchor" href="#_9-待确认问题"><span>9. 待确认问题</span></a></h2><blockquote><p>前端 V2 的<strong>接线契约已定稿</strong>（§6.1 提交回答 / §6.2 语音通道 / §6.3 会话语义）， 剩余待确认的只有<strong>产品口径</strong>，不阻塞开发。</p></blockquote><table><thead><tr><th style="text-align:left;">优先级</th><th style="text-align:left;">事项</th><th style="text-align:left;">当前状态</th><th style="text-align:left;">建议</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>P0</strong></td><td style="text-align:left;"><strong>入口策略</strong>：V2 替换 V1 成为默认入口，还是长期并存（设置页切换）</td><td style="text-align:left;">现状：两版并存，设置页给 <code>?mode=text</code> 入口</td><td style="text-align:left;">需产品定；建议<strong>先并存灰度</strong>，看 V2 的完成率与时长再决定</td></tr><tr><td style="text-align:left;"><strong>P1</strong></td><td style="text-align:left;"><strong>文本模式单价是否与语音一致</strong></td><td style="text-align:left;">后端已按&quot;会话时长&quot;计费（思考时间也算，见 §6.3）</td><td style="text-align:left;">属商业决策；建议先与语音同价，避免早期两套口径</td></tr><tr><td style="text-align:left;"><strong>P1</strong></td><td style="text-align:left;"><strong>记录归一</strong>：文本版与语音版是否同一列表 / 同一详情页</td><td style="text-align:left;">详情页本身就是一问一答文本，天然适配</td><td style="text-align:left;">建议同一列表（用户视角&quot;都是一场面试&quot;）</td></tr><tr><td style="text-align:left;"><strong>P1</strong></td><td style="text-align:left;"><strong>V1 去留</strong>：保留多久、何时下线</td><td style="text-align:left;">下线需同步移除 <code>features/interview/ws.ts</code>、<code>recorder.ts</code> 等音频链路</td><td style="text-align:left;">需产品定；下线前不要动 V1 链路（见后端方案 §5.2 的回归红线）</td></tr></tbody></table><h3 id="_9-1-已定稿、不再作为待确认项" tabindex="-1"><a class="header-anchor" href="#_9-1-已定稿、不再作为待确认项"><span>9.1 已定稿、不再作为待确认项</span></a></h3><table><thead><tr><th style="text-align:left;">项目</th><th style="text-align:left;">定稿内容</th></tr></thead><tbody><tr><td style="text-align:left;">语音识别路线</td><td style="text-align:left;"><strong>方案 A（服务端流式 ASR <code>/ws/asr</code>）</strong>；同声传译插件不进入实现范围（§5.2）。后端已交付，前端 <code>AsrTransport</code> <strong>已实现（2026-09-23，见 §6.2 落地记录）</strong></td></tr><tr><td style="text-align:left;">提交回答</td><td style="text-align:left;">走 <code>/ws/audio</code> 的上行 <code>ANSWER</code>（<strong>不是</strong>流式 HTTP）；下行沿用 <code>THINKING</code> / <code>LLM_REPLY</code></td></tr><tr><td style="text-align:left;">语音输入</td><td style="text-align:left;">独立 <code>/ws/asr</code>（音频进、文本出；不计费、不触发回合）；<strong>使用资格挂靠面试会话</strong>（后端方案 §4.2.5）：必须有进行中的面试才能建连，面试结束由服务端静默回收</td></tr><tr><td style="text-align:left;">语音输入的资源生命周期（前端）</td><td style="text-align:left;">由 <code>useSpeechInput({ enabled, terminated })</code> 收口：暂停 / AI 生成中只 <code>stop()</code>，面试结束 <code>dispose()</code>；非允许状态下<strong>丢弃迟到的识别结果 / 错误 / 超时提示</strong>（§6.2「生命周期收口」）</td></tr><tr><td style="text-align:left;">计费活跃度判据</td><td style="text-align:left;"><strong>只看心跳</strong>；不把「收到 <code>ANSWER</code>」当心跳，也不把&quot;思考&quot;当暂停（§6.3.1）</td></tr><tr><td style="text-align:left;">失联语义</td><td style="text-align:left;"><strong>失联 = 结束</strong>（≠ 暂停）；文字作答阈值 <strong>180 秒</strong>（§6.3.1 定稿块）</td></tr><tr><td style="text-align:left;">无操作自动暂停</td><td style="text-align:left;"><strong>本期不做</strong>（后端方案 §8 P0-1）</td></tr><tr><td style="text-align:left;">结束原因</td><td style="text-align:left;">分档：<code>USER_ENDED</code> 主动结束 / <code>DISCONNECTED</code> 连接层（失联·顶号·传输错误）/ <code>BILLING_EXHAUSTED</code> 余额耗尽 / <code>SYSTEM_ERROR</code> 计费异常 / <code>ASR_ERROR</code> 识别故障 / <code>SESSION_EXPIRED</code> 暂停超时（后端方案 §8 P0-2）</td></tr><tr><td style="text-align:left;">埋点隐私口径</td><td style="text-align:left;">不上报回答原文，只上报长度（§6.4）</td></tr></tbody></table>`,120)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};